echo "C300: c_acc2 (detached)"
P=/workspace/nox/svc/pipeline; mkdir -p $P/acc2
echo  | base64 -d > $P/acc2/pipeline_svc.py
echo  | base64 -d > $P/acc2/nox-chat-c.css
